from h import *
add(6444203,"برسلز اسپراؤٹس سنگتروں کے ساتھ",
"برسلز اسپراؤٹس اور سنگترے ایک رنگ برنگی، میٹھی اور نمکین سائیڈ ڈش بناتے ہیں جو تھینکس گیونگ یا تعطیلات کے کھانے میں خوبصورت اضافہ ہو گی۔",
"12","1/2 کپ",
["1 کھانے کا چمچ سنگترے کا چھلکا","1 درمیانا سنگترہ","1/4 کپ اخروٹ (موٹے کٹے ہوئے)","2 کھانے کے چمچ زیتون کا تیل (تقسیم کر کے)","2 درمیانے شیلوٹ (چھلے ہوئے اور باریک کٹے ہوئے)","2 پاؤنڈ برسلز اسپراؤٹس (تراشے ہوئے اور آدھے کٹے ہوئے)","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ"],
["سنگترے کا چھلکا کدوکش کریں اور ایک چھوٹے رمکن میں ڈال دیں۔ سنگترہ چھیل کر پھانکیں الگ کریں اور ہر پھانک کو آدھا کاٹ لیں؛ الگ رکھ دیں۔ اخروٹ ایک چھوٹی کڑاہی میں ڈالیں اور درمیانی آنچ پر 3 سے 4 منٹ ہلکا بھورا ہونے تک بھونیں۔","ایک بڑی کڑاہی میں درمیانی تیز آنچ پر 1 کھانے کا چمچ تیل گرم کریں۔ شیلوٹ ڈالیں اور 4 سے 5 منٹ ہلکا بھورا ہونے تک بھونیں۔ شیلوٹ کو سوراخ دار چمچ سے نکال کر الگ رکھ دیں۔ باقی تیل پین میں ڈالیں اور پھر اسپراؤٹس ڈالیں۔ اسپراؤٹس کو 10 سے 15 منٹ بھونیں، جب تک بھورے نہ ہو جائیں اور اچھی طرح پک نہ جائیں۔ سنگترے کی پھانکیں، سنگترے کا چھلکا اور بھونے ہوئے شیلوٹ ڈالیں اور 2 منٹ پکائیں۔","اسپراؤٹس میں نمک اور کالی مرچ ڈالیں اور ایک بڑے سرونگ پیالے میں رکھیں۔ اوپر اخروٹ ڈال کر پیش کریں۔"])
add(6445063,"جھینگے کریمی ارگولا پیسٹو کے ساتھ",
"یونانی دہی اور کاجو پوچ کیے ہوئے جھینگوں یا مچھلی کے فلیٹ پر ڈالنے کے لیے مزیدار کریمی پیسٹو بناتے ہیں۔",
"6","بھرپور 1/3 کپ",
["3 کپ پانی","1 کھانے کا چمچ بغیر نمک کا مسالا (سالٹ فری اسپائیک یا مسز ڈیش)","1 1/4 پاؤنڈ جھینگے (درمیانے، چھلے ہوئے اور آنت نکالے ہوئے)","4 کپ ارگولا","1/4 کپ سادہ بغیر چکنائی والا یونانی دہی","2 لہسن کی جوئیں","1 کھانے کا چمچ زیتون کا تیل","1/4 کپ بغیر نمک کے کاجو","1/4 کپ پارمیزان چیز (کدوکش کی ہوئی)","1/4 چائے کا چمچ کالی مرچ"],
["ایک درمیانے ساس پین میں پانی اور بغیر نمک کا مسالا ابال لیں۔ آنچ بالکل ہلکی ابال تک کم کر دیں اور جھینگے ڈالیں۔ 6 منٹ پکائیں یا جب تک جھینگے گلابی نہ ہو جائیں اور بس پک جائیں۔","جب جھینگے پک رہے ہوں تو ارگولا، دہی، لہسن، زیتون کا تیل، کاجو، پارمیزان چیز اور کالی مرچ بلینڈر یا فوڈ پروسیسر میں ڈالیں۔ ہموار ہونے تک بلینڈ کریں۔","جھینگوں کا پانی نکال دیں اور جب وہ ابھی گرم ہوں تو پیسٹو میں ملا دیں۔"])
add(6446820,"بجٹ کے موافق بریزڈ چکن ران مشروم کے ساتھ",
"صحت بخش کھانا بجٹ میں بھی کھایا جا سکتا ہے اور یہ رات کا کھانا اس کا ثبوت ہے! چکن کی رانیں چکن بریسٹ سے سستی ہیں اور اچھی تبدیلی ہو سکتی ہیں۔ یہ ایک مزیدار، کم کاربوہائیڈریٹ، بجٹ کے موافق کھانا بناتا ہے۔",
"4","1 چکن ران 1/4 کپ مشروم کے ساتھ",
["1 کھانے کا چمچ زیتون کا تیل","1 پاؤنڈ بغیر ہڈی اور بغیر کھال کی چکن رانیں (بغیر ہڈی، بغیر کھال)","1 چائے کا چمچ سمن نباتی (مارجرین) (ٹرانس فیٹ سے پاک)","1/2 درمیانی پیاز (باریک چوکور کٹی ہوئی)","8 اونس کٹے ہوئے مشروم (کٹے ہوئے)","3 کھانے کے چمچ بالسامک سرکہ","1 1/2 کپ کم سوڈیم چکن شوربہ"],
["ایک بڑے ڈچ اوون میں تیل درمیانی تیز آنچ پر گرم کریں۔","چکن کی رانیں ڈالیں اور ہر طرف 3 منٹ بھونیں۔ پین سے نکال کر الگ رکھ دیں۔","پین میں مارجرین ڈالیں اور پگھلائیں۔ پیاز ڈالیں اور 2 منٹ بھونیں۔ مشروم ڈالیں اور 3-5 منٹ بھونیں جب تک پانی نہ چھوڑ دیں؛ بار بار ہلاتے رہیں۔","پین میں بالسامک سرکہ ڈالیں اور مشروم کے ساتھ 1 منٹ پکائیں۔ چکن کی رانیں پین میں واپس ڈالیں اور مشروم چکن کے اوپر رکھ دیں۔ چکن شوربہ پین میں ڈالیں۔","چکن شوربے کو ابال لیں۔ آنچ درمیانی دھیمی کر دیں، پین کو بھاری، مضبوطی سے بند ہونے والے ڈھکن سے ڈھانپ دیں، اور 25 منٹ ہلکی آنچ پر پکائیں۔"])
add(6446864,"پھلوں سے میٹھی کی گئی باربی کیو ساس",
"دکان سے خریدی گئی زیادہ تر باربی کیو ساسز میں اضافی چینی بھری ہوتی ہے۔ یہ تیز اور آسان گھریلو ساس اپنی مٹھاس سیب کی چٹنی (ایپل ساس) سے حاصل کرتی ہے! یہ ترکیب تھوڑی مقدار کے لیے ہے، لیکن آپ اسے آسانی سے دوگنا، تین گنا یا چار گنا بھی کر سکتے ہیں۔ بچی ہوئی ساس بند مرتبان میں فریج میں ایک ہفتے تک رکھیں۔",
"4","2 کھانے کے چمچ",
["1/4 کپ بغیر اضافی چینی کا کیچپ","3 کھانے کے چمچ بغیر میٹھے کی ایپل ساس (سیب کی چٹنی)","1 چائے کا چمچ سیب کا سرکہ","1/2 چائے کا چمچ کالی مرچ","1/2 چائے کا چمچ اسموکڈ پیپریکا"],
["مائع ناپنے والے کپ میں تمام اجزا ہلا کر ملا لیں۔ پیش کریں، یا بند مرتبان میں فریج میں 1 ہفتے تک رکھیں۔"])
add(6447164,"شملہ مرچ پاپرز",
"ان پاپرز میں تھوڑی اور تیزی کے لیے کچلی ہوئی لال مرچ کے ٹکڑوں کی مقدار اپنی پسند کے مطابق بڑھا دیں۔",
"12","2 پاپرز",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","12 چھوٹی منی میٹھی مرچیں","2 قتلے ٹرکی بیکن (چوکور کٹے ہوئے)","1/2 کپ پیاز (چوکور کٹی ہوئی)","4 اونس بغیر چکنائی والا کریم چیز (کمرے کے درجہ حرارت پر)","2 اونس نرم بکری کی چیز (کمرے کے درجہ حرارت پر)","1/4 چائے کا چمچ کچلی ہوئی لال مرچ کے ٹکڑے","1 قتلہ پورے گندم کی ڈبل روٹی (ٹوسٹ کی ہوئی)","1 لہسن کی جوئی (باریک کٹی ہوئی)","1 کھانے کا چمچ پارمیزان چیز (کدوکش کی ہوئی)"],
["اوون کو 375° فارن ہائیٹ پر پہلے سے گرم کریں۔ بیکنگ ٹرے پر کوکنگ اسپرے لگا دیں۔ الگ رکھ دیں۔","ہر مرچ کو لمبائی میں آدھا کاٹیں پھر کوئی بھی بیج اور جھلی نکال دیں۔","بیکن کو کوکنگ اسپرے لگے نان اسٹک سوٹے پین میں درمیانی آنچ پر ڈالیں اور کرکرا ہونے تک پکائیں۔ کاغذی تولیے پر پانی نکال کر الگ رکھ دیں۔","بیکن پکانے والے پین میں پیاز ڈالیں اور ضرورت ہو تو مزید کوکنگ اسپرے لگائیں۔ پیاز کو وقفے وقفے سے ہلاتے ہوئے شفاف ہونے تک پکائیں۔ ٹھنڈا ہونے کے لیے الگ رکھ دیں۔","ایک چھوٹے پیالے میں کریم چیز اور بکری کی چیز ملا لیں۔ بیکن، پیاز اور کچلی ہوئی لال مرچ ڈالیں۔ ہلا کر ملا لیں۔","ٹوسٹ کی ہوئی ڈبل روٹی کو فوڈ پروسیسر میں لہسن اور پارمیزان چیز کے ساتھ پیس لیں۔ ایک چھوٹے پیالے میں الگ رکھ دیں۔","چیز کا آمیزہ ہر مرچ کے آدھے حصے میں چمچ سے بھریں (ہر پاپر کے لیے آمیزے کا 1 چائے کا چمچ)، اور پھر پاپر کی چیز والی طرف کو پورے گندم کے بریڈ کرمبز کے آمیزے میں دبائیں۔ تیار کی ہوئی بیکنگ ٹرے پر بریڈ کرمبز والی طرف اوپر کر کے رکھیں اور ہر ایک پر ہلکا سا کوکنگ اسپرے کریں۔","پاپرز کو تقریباً 20 منٹ بیک کریں یا جب تک مرچیں نرم نہ ہو جائیں اور بریڈ کرمبز سنہری بھورے نہ ہو جائیں۔"])
add(6448197,"پیاز، پالک اور آرٹیچوک ڈپ",
"اس ڈپ کا لطف تازہ کٹی ہوئی سبزیوں جیسے بیبی گاجر، اجوائن کی ڈنڈیاں، کٹے ہوئے کھیرے، یا منی شملہ مرچوں کے ساتھ اٹھائیں۔ یہ آپ کی اگلی دعوت کے دسترخوان میں زیادہ سبزیاں (اور اس طرح زیادہ غذائی اجزا) شامل کرنے کا ایک آسان طریقہ ہے!",
"20","2 کھانے کے چمچ",
["1 چائے کا چمچ زیتون کا تیل","1 درمیانی پیاز (باریک چوکور کٹی ہوئی)","1 (15 اونس) ڈبہ آرٹیچوک ہارٹس (پانی نکالے ہوئے اور دھوئے ہوئے)","1/2 چائے کا چمچ خشک تھائم","6 اونس پالک (تازہ، موٹی کٹی ہوئی)","1/4 کپ ہلکی مایونیز","4 پھانکیں ہلکی پھیلائی جانے والی چیز کی پھانکیں (جیسے لافنگ کاؤ)","2 کھانے کے چمچ پارمیزان چیز (تازہ کدوکش کی ہوئی، تقسیم کر کے استعمال کریں)","2 کھانے کے چمچ لیموں کا رس (1 درمیانے لیموں سے)"],
["اوون کو 350°F پر پہلے سے گرم کریں۔","ایک بڑی کڑاہی میں زیتون کا تیل درمیانی آنچ پر گرم کریں۔ پیاز ڈالیں اور بار بار ہلاتے ہوئے 5 منٹ بھونیں۔ آرٹیچوک اور تھائم ڈالیں اور مزید 3 منٹ پکائیں یا جب تک سبزیاں بھورا ہونا شروع نہ ہو جائیں۔ پالک ڈالیں اور مزید 1-2 منٹ پکائیں جب تک پالک مرجھا نہ جائے۔ کڑاہی کو چولھے سے ہٹا دیں۔","مائیکرو ویو کے قابل پیالے میں ہلکی مایونیز، چیز کی پھانکیں اور 1 کھانے کا چمچ پارمیزان چیز ملا لیں۔ مائیکرو ویو میں 30 سیکنڈ گرم کریں تاکہ نرم ہو جائے، پھر اچھی طرح ملا لیں۔ ضرورت ہو تو آمیزے کو 15 سیکنڈ کے وقفوں میں گرم کریں جب تک چیز نرم نہ ہو جائے اور مایونیز کے ساتھ آسانی سے مل نہ جائے۔","چیز کا آمیزہ اور لیموں کا رس بھونی ہوئی سبزیوں میں ڈالیں اور اچھی طرح ملا لیں۔ ڈپ کو ایک چھوٹی بیکنگ ڈش میں پھیلا دیں، اوپر باقی 1 کھانے کا چمچ پارمیزان چیز ڈالیں، اور اوون میں 5 منٹ بیک کریں۔ گرم پیش کریں۔"])
add(6450804,"جھینگا فاہیٹاز",
"اس ڈش کو جکاما کی ڈنڈیوں اور تازہ گواکامولے کے ساتھ پیش کریں۔ اگر چاہیں تو مختلف رنگوں کی مرچیں یا جامنی پیاز استعمال کر کے اس رنگ برنگی ڈش کو اور بھی جاندار بنا سکتے ہیں۔",
"5","2 فاہیٹاز",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","1 پاؤنڈ جھینگے (درمیانے، چھلے ہوئے اور آنت نکالے ہوئے)","1 چائے کا چمچ زیتون کا تیل","1 درمیانی سرخ شملہ مرچ (باریک کٹی ہوئی)","1 درمیانی ہری شملہ مرچ (باریک کٹی ہوئی)","1 درمیانی پیاز (باریک کٹی ہوئی)","1/4 کپ پانی","1/2 کھانے کا چمچ چلی پاؤڈر","1/4 چائے کا چمچ لال مرچ (کیین) (اختیاری)","1/4 چائے کا چمچ زیرہ","1/2 چائے کا چمچ نمک","1/2 چائے کا چمچ کالی مرچ","10 چھوٹے مکئی کے ٹورٹیلا"],
["ایک بڑی نان اسٹک کڑاہی پر کوکنگ اسپرے لگا دیں۔ جھینگوں کو درمیانی آنچ پر تقریباً 2 منٹ پکائیں۔ جھینگوں کو پین سے نکال کر الگ رکھ دیں۔","پین میں تیل ڈال کر گرم کریں۔ شملہ مرچیں اور پیاز ڈالیں اور تقریباً 7 منٹ پکائیں یا جب تک بھورے ہونا شروع نہ ہو جائیں۔ جھینگے اور ان کا کوئی بھی رس پین میں واپس ڈالیں۔","پانی اور مسالے ڈالیں، بشمول نمک اور کالی مرچ۔ آمیزے کو ابال لیں؛ آنچ کم کر دیں اور ہلکی آنچ پر پکائیں جب تک پانی خشک نہ ہو جائے۔ جھینگے اور شملہ مرچیں مکئی کے ٹورٹیلا میں رکھ کر پیش کریں۔"])
add(6451442,"ٹوفو اور سبزیوں کی سیخیں براؤن چاول کے ساتھ",
"صحت بخش رات کے کھانے کے لیے گرل جلائیں، ٹوفو اور سبزیوں کی سیخیں۔ ایشیائی طرز کا مزیدار میرینیڈ اس ذیابیطس کے لیے موزوں کھانے میں ذائقے کی بھرپور لہر ڈالتا ہے۔",
"4","2 سیخیں + 1/3 کپ پکے ہوئے براؤن چاول",
["2 کھانے کے چمچ کم سوڈیم سویا ساس","2 کھانے کے چمچ چاول کا سرکہ","1 کھانے کا چمچ تل کا تیل","1 کھانے کا چمچ میپل شربت","2 لہسن کی جوئیں (باریک کٹی ہوئی)","1 چائے کا چمچ تازہ ادرک (کدوکش کی ہوئی)","16 اونس سخت ٹوفو (دبایا ہوا اور چوکور ٹکڑوں میں کٹا ہوا)","1 درمیانی سرخ پیاز (بڑے ٹکڑوں میں کٹی ہوئی)","2 ثابت شملہ مرچیں (بڑے ٹکڑوں میں کٹی ہوئی)","2 درمیانی پیلی اسکوائش (گول قتلوں میں کٹی ہوئی)","1 1/3 کپ پکے ہوئے براؤن چاول"],
["ایک پیالے میں سویا ساس، چاول کا سرکہ، تل کا تیل، میپل شربت یا ایگیو نیکٹر، باریک کٹا لہسن اور کدوکش کی ہوئی ادرک پھینٹ کر ملا لیں تاکہ میرینیڈ بن جائے۔","دبائے ہوئے ٹوفو کو چوکور ٹکڑوں میں کاٹ لیں اور ایک اتھلی ڈش میں رکھیں۔ آدھا میرینیڈ ٹوفو پر ڈالیں اور یقینی بنائیں کہ ہر ٹکڑا اچھی طرح لگ جائے۔ کم از کم 30 منٹ میرینیٹ ہونے دیں۔","جب ٹوفو میرینیٹ ہو رہا ہو تو سبزیاں تیار کریں۔ میرینیٹ کیا ہوا ٹوفو، سرخ پیاز کے ٹکڑے، شملہ مرچ کے ٹکڑے، اور پیلی اسکوائش کے گول قتلے باری باری سیخوں میں پرو دیں۔","گرل یا گرل پین کو درمیانی تیز آنچ پر پہلے سے گرم کریں۔","سیخوں کو تقریباً 10–15 منٹ گرل کریں، وقفے وقفے سے پلٹتے ہوئے، جب تک ٹوفو سنہری نہ ہو جائے اور سبزیاں ہلکی جل کر نرم نہ ہو جائیں۔ اضافی ذائقے کے لیے گرل کرتے وقت سیخوں پر باقی میرینیڈ کا برش پھیریں۔","پک جانے کے بعد سیخوں کو گرل سے اتار لیں اور پیش کرنے سے پہلے چند منٹ آرام کرنے دیں۔","پکے ہوئے براؤن چاول کے ساتھ پیش کریں، فی حصہ 1/3 کپ۔"])
add(6451648,"ہرا دھنیا لائم کینوا",
"کینوا میں کسی بھی دوسرے اناج سے زیادہ پروٹین ہوتا ہے۔ یہ گلوٹین سے پاک ہے، فی حصہ 2 گرام ریشہ رکھتا ہے، اور ہر اس ترکیب کے لیے ایک صحت بخش متبادل ہے جس میں چاول استعمال ہوتے ہوں۔",
"6","½ کپ",
["1 کھانے کا چمچ کینولا تیل","1 چھوٹی پیاز (کٹی ہوئی)","2 لہسن کی جوئیں (باریک کٹی ہوئی)","1 کپ کینوا (خشک)","2 کپ کم سوڈیم سبزیوں کا شوربہ (بغیر چکنائی، (ضرورت ہو تو گلوٹین سے پاک))","4 کھانے کے چمچ تازہ لائم کا رس (2 درمیانے لائم سے)","1/2 کپ تازہ ہرا دھنیا (کٹا ہوا)"],
["ایک بڑی کڑاہی میں تیل درمیانی آنچ پر گرم کریں۔ پیاز ڈالیں اور 3 سے 4 منٹ پکائیں۔ لہسن ڈالیں اور 30 سیکنڈ پکائیں۔ آنچ ہلکی کر دیں اور کینوا ڈالیں۔ ہلکی آنچ پر 1-2 منٹ مسلسل ہلاتے ہوئے پکائیں تاکہ کینوا جل نہ جائے۔","سبزیوں کا شوربہ اور 1 لائم کا رس ڈالیں اور ابال لیں۔ آنچ ہلکی کر دیں، ڈھانپ دیں، اور 15 منٹ یا پک جانے تک ہلکی آنچ پر پکائیں۔ چولھے سے اتار لیں۔","1 لائم کا رس اور کٹا ہوا ہرا دھنیا ملا دیں۔"])
add(6452003,"فلی چیز اسٹیک بھری ہوئی شملہ مرچیں",
"یہ فلی چیز اسٹیک سے بھری ہوئی شملہ مرچیں اصل کے تمام لذیذ ذائقے رکھتی ہیں—لیکن رول (بن) کے بغیر۔ ڈبل روٹی کی جگہ شملہ مرچ استعمال کرنے سے کاربوہائیڈریٹ کم ہوتے ہیں اور ریشہ اور غذائی اجزا بھی شامل ہوتے ہیں۔ یہ کم کاربوہائیڈریٹ والا بہترین رات کا کھانا ہے جو خون میں گلوکوز (بلڈ شوگر) کو مستحکم رکھنے میں مدد دے سکتا ہے۔",
"4","1 بھری ہوئی شملہ مرچ",
["2 ثابت ہری شملہ مرچیں (لمبائی میں آدھی کٹی ہوئی، بیج نکالے ہوئے)","1 چائے کا چمچ ایکسٹرا ورجن زیتون کا تیل","1 بڑی پیاز (آدھی کٹی ہوئی اور باریک قتلے کی ہوئی)","8 اونس کریمینی (بیبی بیلا) مشروم (باریک کٹے ہوئے)","12 اونس ٹاپ راؤنڈ اسٹیک (چکنائی ہٹائی ہوئی، باریک کٹی ہوئی)","1 کھانے کا چمچ اطالوی مسالا","1/2 چائے کا چمچ کالی مرچ","1/4 چائے کا چمچ نمک","1 کھانے کا چمچ ورسٹرشائر ساس","1/4 کپ جزوی سکِم موزریلا (کدوکش کی ہوئی)","2 ڈنٹھل ہری پیاز (اسکیلین) (کٹی ہوئی)"],
["اوون کو 375 ڈگری فارن ہائیٹ پر پہلے سے گرم کریں۔ شملہ مرچ کے آدھے حصے بیکنگ ٹرے پر کٹی ہوئی طرف اوپر کر کے سجائیں۔ تقریباً 30 منٹ بیک کریں یا جب تک وہ نرم ہو جائیں لیکن اپنی شکل برقرار رکھنے کے لیے کافی سخت رہیں۔","جب مرچیں اوون میں ہوں تو ایک بڑی کڑاہی میں زیتون کا تیل درمیانی آنچ پر گرم کریں۔ کٹی ہوئی پیاز ڈالیں اور تقریباً 4–5 منٹ، وقفے وقفے سے ہلاتے ہوئے، پکائیں جب تک وہ نرم نہ ہو جائیں اور بھورا ہونا شروع نہ ہو جائیں۔","مشروم ڈالیں اور مزید 5 منٹ پکاتے رہیں، تاکہ وہ اپنی نمی چھوڑ دیں۔","اسٹیک کے قتلے اطالوی مسالے، کالی مرچ اور نمک کے ساتھ پین میں ڈالیں۔ 3–5 منٹ بار بار ہلاتے ہوئے پکائیں جب تک اسٹیک بھورا اور اچھی طرح پک نہ جائے۔","ورسٹرشائر ساس ڈالیں، ہلا کر ملا لیں، اور کڑاہی کو چولھے سے ہٹا دیں۔","اوون کو بروئل پر کر دیں۔","ہر شملہ مرچ کے آدھے حصے میں اسٹیک کے آمیزے کا برابر حصہ بھریں اور چیز چھڑکیں۔","مرچوں کو اوون میں واپس رکھیں اور 2–3 منٹ بروئل کریں، یا جب تک چیز مکمل پگھل نہ جائے اور ذرا سنہری نہ ہو جائے۔","پیش کرنے کے لیے اوپر کٹی ہوئی ہری پیاز ڈالیں۔"])
add(6452790,"لیموں کا سوربے",
"یہ کم کاربوہائیڈریٹ لیموں کا سوربے ایک تازگی بخش اور کھٹا منجمد میٹھا ہے جو زیادہ چینی اور کیلوریز کے بغیر لیموں کے ذائقے کی لہر دیتا ہے۔ اسے تازگی بخش میٹھے کے طور پر کھائیں، جو ذیابیطس کے کھانے کے منصوبے پر عمل کرتے ہوئے آپ کی میٹھے کی خواہش پوری کرنے کے لیے بہترین ہے۔",
"4","1/2 کپ",
["4 لیموں کا رس (رس نچوڑا ہوا)","1/2 کپ پانی","2 چائے کے چمچ مائع اسٹیویا میٹھا"],
["ایک پیالے میں لیموں کا رس، پانی اور اسٹیویا پھینٹ کر ملا لیں۔","آئس کریم میکر میں ڈالیں اور بنانے والے کی ہدایات کے مطابق چلائیں۔","نرم سوربے کے لیے اسے فوراً کھائیں۔ زیادہ ٹھوس ساخت کے لیے فریزر کے قابل ڈبے میں منتقل کریں اور 2 گھنٹے فریز کریں۔"])
add(6453245,"لذیذ سبزیوں کے انڈے کے مفنز",
"سبزیوں کے یہ لذیذ انڈے کے مفنز ایک اٹھاؤ اور چلو ناشتہ ہیں جو ریشے، پروٹین اور رنگ برنگی سبزیوں سے بھرپور ہیں۔ پورے گندم کے آٹے، کدوکش کی ہوئی سبزیوں اور کم چکنائی والی چیز کی صرف ہلکی سی مقدار کی بنیاد کے ساتھ، یہ بھاری ہوئے بغیر پیٹ بھرنے والے ہیں۔ غذائی اجزا کا متوازن امتزاج انہیں ذیابیطس کو سنبھالنے والوں کے لیے بہترین انتخاب بناتا ہے۔ یہ ڈیش (DASH، ہائی بلڈ پریشر روکنے کا غذائی طریقہ)، سبزی خوروں کے لیے اور کم چکنائی والی ترکیب ہے۔",
"4","2 مفنز",
["2 بڑی زوکینی (کدوکش کی ہوئی اور نچوڑ کر خشک کی ہوئی)","1 بڑی گاجر (کدوکش کی ہوئی)","1/4 کپ سرخ شملہ مرچ (باریک چوکور کٹی ہوئی)","1/4 کپ سرخ پیاز (باریک چوکور کٹی ہوئی)","2 بڑے انڈے","2 اونس مائع انڈے کی سفیدی","1/4 کپ کم چکنائی والا دودھ","1/2 کپ پورے گندم کا آٹا","1/2 چائے کا چمچ بیکنگ پاؤڈر","1/4 چائے کا چمچ کالی مرچ","1/8 چائے کا چمچ اسموکڈ پیپریکا","1/4 کپ کم چکنائی والی کدوکش کی ہوئی چیڈر چیز"],
["اوون کو 375°F (190° سیلسیس) پر پہلے سے گرم کریں اور مفن ٹرے میں 8 کاغذی لائنر لگائیں یا خانوں پر کوکنگ اسپرے سے ہلکی چکنائی لگا دیں۔","زوکینی اور گاجر کدوکش کریں، پھر صاف تولیے سے اضافی نمی نچوڑ دیں۔ سرخ شملہ مرچ اور سرخ پیاز کو چوکور کاٹ لیں اور تمام سبزیاں ایک پیالے میں ملا لیں۔","ایک درمیانے پیالے میں انڈے، انڈوں کی سفیدی اور کم چکنائی والا دودھ اچھی طرح ملنے تک پھینٹ لیں۔","ایک اور پیالے میں پورے گندم کا آٹا، بیکنگ پاؤڈر، کالی مرچ اور اسموکڈ پیپریکا ملا لیں۔","خشک اجزا کو آہستہ آہستہ گیلے اجزا میں ملائیں، آہستگی سے ہلاتے ہوئے بس ملنے تک۔ کدوکش کی ہوئی سبزیاں اور چیڈر چیز آمیزے میں ڈالیں اور یکساں طور پر تقسیم ہونے تک ملائیں۔","آمیزے کو تیار کیے ہوئے 8 مفن کپوں میں برابر تقسیم کریں۔ ہر ایک کو تقریباً 3/4 بھر دیں۔","18–22 منٹ بیک کریں، یا جب تک مفن کے بیچ میں ڈالی گئی ٹوتھ پک صاف نہ نکلے۔","مفنز کو ٹرے میں 5 منٹ ٹھنڈا ہونے دیں، پھر تار کی جالی پر منتقل کریں۔ گرم یا کمرے کے درجہ حرارت پر پیش کریں۔"])
add(6454224,"میمنے کے چاپ آلو اور بہار کی سبزیوں کے ساتھ",
"میمنے کا گوشت ایسٹر کے موسم کے لیے بہترین ہے اور سال کے کسی بھی وقت کے لیے ایک خاص چیز۔ میمنے کے لوئن چاپ نرم، کم چکنائی والا ٹکڑا ہیں جو گرل پر آسانی سے پک جاتے ہیں۔ جب آپ معمول کے چکن اور بیف سے تھک جائیں تو یہ آزمانے کا اچھا انتخاب ہیں۔ ایسپیرگس اور گاجر جیسی بہار کی سبزیوں کے ساتھ پیش کریں۔",
"4","1-2 میمنے کے چاپ + 1 آلو، 5 ایسپیرگس کی ڈنڈیاں اور 2 گاجریں",
["1 کھانے کا چمچ + 2 چائے کے چمچ ایکسٹرا ورجن زیتون کا تیل (تقسیم کر کے استعمال کریں)","2 لہسن کی جوئیں (باریک کٹی ہوئی)","1/2 چائے کا چمچ کوشر نمک","1/4 چائے کا چمچ کالی مرچ","3 کھانے کے چمچ تازہ روزمیری (کٹی ہوئی، تقسیم کر کے استعمال کریں)","1 پاؤنڈ کم چکنائی والے میمنے کے لوئن چاپ (چکنائی ہٹائی ہوئی)","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","4 چھوٹے سرخ آلو (چار حصوں میں کٹے ہوئے، چھلکے کے ساتھ)","8 درمیانی گاجریں (آدھی کٹی ہوئی)","1 گچھا ایسپیرگس (تقریباً 20 ڈنڈیاں، تراشی ہوئی)"],
["1 کھانے کا چمچ زیتون کا تیل، لہسن، نمک، کالی مرچ اور روزمیری ملا لیں۔ میمنے کے چاپ پر مکمل لگا دیں اور فریج میں 2 گھنٹے میرینیٹ کریں۔ گرل کرنے سے 30 منٹ پہلے فریج سے نکال لیں۔","اوون کو 450°F پر پہلے سے گرم کریں۔ بیکنگ ٹرے پر کوکنگ اسپرے لگا دیں","آلو ایک پیالے میں رکھیں اور 1 چائے کا چمچ زیتون کا تیل اور 2 کھانے کے چمچ کٹی ہوئی روزمیری کے ساتھ ملا دیں۔ انہیں بیکنگ ٹرے پر رکھیں اور پہلے سے گرم اوون کے بیچ میں رکھ کر 10 منٹ بھونیں۔","اسی پیالے میں گاجریں رکھیں اور باقی تیل اور روزمیری کے ساتھ ملا دیں۔ ایسپیرگس کے ساتھ آلوؤں میں شامل کریں اور مزید 10 منٹ بھونتے رہیں۔","اسی دوران، گرل کو پہلے سے گرم کریں اور میمنے کے چاپ براہ راست گرل پر رکھیں۔ 5 منٹ گرل کریں، پھر چاپ پلٹیں اور مزید 3 – 5 منٹ گرل کرتے رہیں۔ ان کا اندرونی درجہ حرارت 135°F تک پہنچنا چاہیے۔"])
add(6454316,"ہوائی طرز کے شیو کیے ہوئے برسلز اسپراؤٹس",
"برسلز اسپراؤٹس کو شیو کرنے کے کئی طریقے ہیں۔ ایک طریقہ ہاتھ سے ہے—بس ہر اسپراؤٹ کا ڈنٹھل والا سرا تراش دیں تاکہ وہ کٹنگ بورڈ پر ہموار بیٹھے۔ پھر شیف کی چھری سے اسے بہت پتلے قتلوں میں کاٹ لیں۔ (سرا تراشنے سے وہ لڑھکتا نہیں۔) دوسرا طریقہ فوڈ پروسیسر کا استعمال ہے۔ بس اسپراؤٹس کو چوٹ (شوٹ) میں ڈالیں اور سلائسنگ اٹیچمنٹ کو کام کرنے دیں!",
"6","1/2 کپ",
["16 اونس تازہ برسلز اسپراؤٹس","1 کھانے کا چمچ کینولا تیل","1 کھانے کا چمچ براؤن شوگر","1/2 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","1 (8 اونس) ڈبہ جوس میں انناس کے ٹکڑے (اچھی طرح پانی نکالے ہوئے)","1 کھانے کا چمچ میکاڈیمیا گری (کٹی ہوئی)"],
["برسلز اسپراؤٹس کے تنوں کے نچلے حصے کاٹ دیں، پھر اسپراؤٹس کو چھری سے بہت پتلے قتلوں میں کاٹ لیں، یا فوڈ پروسیسر میں سلائس کریں۔","ایک بڑی کڑاہی میں درمیانی آنچ پر تیل گرم ہونے تک گرم کریں۔ برسلز اسپراؤٹس کو 5 سے 7 منٹ بھونیں، وقفے وقفے سے ہلاتے ہوئے، یا جب تک بھورا ہونا شروع نہ ہو جائیں۔ زیادہ کرکرے برسلز اسپراؤٹس کے لیے چند منٹ مزید بھونیں۔","براؤن شوگر، نمک، کالی مرچ اور انناس ملا دیں۔ 3 سے 5 منٹ پکائیں، یا جب تک اچھی طرح گرم نہ ہو جائیں۔ میکاڈیمیا گری چھڑکیں اور پیش کریں۔"])
add(6456214,"پھول گوبھی کے چاول اور پھلیوں کے فاہیٹا باؤلز",
"اس ذیابیطس کے لیے موزوں اور ویگن کھانے میں پھلیاں آپ کے کھانے میں پودوں سے حاصل ہونے والی مزیدار پروٹین شامل کرتی ہیں۔ پھول گوبھی سے چاول بنانا اضافی کاربوہائیڈریٹ شامل کیے بغیر اپنی خوراک میں زیادہ غذائی اجزا حاصل کرنے کا بہترین طریقہ ہے۔ تھوڑی اضافی چٹخار کے لیے اپنے باؤل پر تازہ ہرا دھنیا یا سالسا ڈالیں۔",
"4","1 باؤل",
["1 سر پھول گوبھی (درمیانی)","2 کھانے کے چمچ زیتون کا تیل","1 (15 اونس) ڈبہ کالی پھلیاں (بغیر اضافی نمک، پانی نکالی ہوئی اور دھوئی ہوئی)","1 درمیانی سرخ شملہ مرچ (باریک کٹی ہوئی)","1 درمیانی پیلی شملہ مرچ (باریک کٹی ہوئی)","1 درمیانی سرخ پیاز (باریک کٹی ہوئی)","2 چائے کے چمچ پسا ہوا زیرہ","1 چائے کا چمچ اسموکڈ پیپریکا","1/2 چائے کا چمچ چلی پاؤڈر","1/2 چائے کا چمچ کوشر نمک","1/2 چائے کا چمچ کالی مرچ","1 درمیانا لائم (آدھا کٹا ہوا)","2 کھانے کے چمچ تازہ ہرا دھنیا (کٹا ہوا، سجاوٹ کے لیے)"],
["فوڈ پروسیسر میں پھول گوبھی کو چاول جیسا ہونے تک پلس کریں۔ الگ رکھ دیں۔","ایک بڑی کڑاہی میں زیتون کا تیل درمیانی آنچ پر گرم کریں۔ کٹی ہوئی شملہ مرچیں اور سرخ پیاز ڈالیں۔ سبزیاں نرم ہونے تک بھونیں، تقریباً 5–7 منٹ۔","چاول کی شکل کی پھول گوبھی کڑاہی میں ڈالیں۔ پسا ہوا زیرہ، اسموکڈ پیپریکا، چلی پاؤڈر، کوشر نمک اور کالی مرچ چھڑکیں۔ اچھی طرح ملا لیں۔","پھول گوبھی کے آمیزے کو مزید 8–10 منٹ، وقفے وقفے سے ہلاتے ہوئے، پکائیں جب تک پھول گوبھی نرم نہ ہو جائے۔","کالی پھلیاں ملا دیں اور مزید 3–5 منٹ پکائیں جب تک ہر چیز اچھی طرح گرم نہ ہو جائے۔","آمیزے پر لائم کا رس نچوڑیں اور ہلا دیں۔","پھول گوبھی کے چاول اور پھلیوں کے فاہیٹا آمیزے کو پیالوں میں تقسیم کریں۔ فوراً پیش کریں۔ چاہیں تو تازہ ہرے دھنیے سے سجائیں۔"])
